    'culture': _items('culture', [
      {'name': 'جشن نوروز', 'note': 'آغاز سال نو خورشیدی و از مهم‌ترین اعیاد مشترک منطقه؛ در هزارستان با دید و بازدید خانوادگی و سبزی‌های بهاری همراه است.', 'full': 'نوروز، آغاز سال نو خورشیدی و بازگشت بهار، در نخستین روز حمل جشن گرفته می‌شود و چهل روز ادامه می‌یابد. این جشن میراث مشترک همه‌ی مردمان فلات ایران و آسیای میانه است و هزاره‌ها نیز، در کنار تاجیک‌ها، ازبک‌ها و دیگر اقوام افغانستان، آن را با شور فراوان برگزار می‌کنند.\\n\\nدر خانواده‌های هزاره، آماده‌سازی نوروز از هفته‌ها پیش با خانه‌تکانی و دوختن یا خریدن لباس نو آغاز می‌شود. سفره‌ی هفت‌میوه — آمیزه‌ای از کشمش، چهارمغز، بادام، پسته، زردآلوی خشک، سنجد و جلغوزه که در آب خیسانده می‌شود — از رسوم ثابت این روزهاست. سبزه‌ی نوروزی و سمنک (حلوای جوانه‌ی گندم) نیز در بسیاری از خانه‌ها آماده می‌شود.\\n\\nدر مزار شریف، مرکز بزرگ‌ترین جشن نوروزی افغانستان، آیین اهتزاز جهنده (برافراشتن پرچم) بر بام زیارت حضرت علی برگزار می‌شود؛ پرچمی که به باور مردم، لمس آن شفابخش است و چهل روز برافراشته می‌ماند. هم‌زمان، میله‌ی گل سرخ — جشنواره‌ی شکوفایی لاله‌های وحشی در باغ‌های اطراف مزار — هزاران تن از سراسر کشور، از جمله شمار زیادی هزاره، را گرد هم می‌آورد. در بامیان و مناطق مرکزی نیز نوروز با کوچه‌گردی، بزکشی و دید و بازدید خانوادگی همراه است.'},
      {'name': 'سوزن‌دوزی هزارگی', 'note': 'هنر دست‌دوزی سنتی با نگین و نخ‌های رنگی که عمدتاً روی چادر، کلاه و لباس زنانه انجام می‌شود.', 'full': 'سوزن‌دوزی هزارگی یکی از ظریف‌ترین سنت‌های دست‌ورزی زنان هزاره است؛ هنری که برخلاف بسیاری از سوزن‌دوزی‌های آزاد منطقه، بر پایه‌ی «شمارش تار» (counted-thread) پیش می‌رود — یعنی نخ به‌دقت و بر اساس شمارش تارهای پارچه دوخته می‌شود، نه آزادانه.\\n\\nاز مهم‌ترین کوک‌های به‌کاررفته می‌توان به کوک ضربدری و استخوان‌شاهی برای جزئیات ریز، کوک دوبل (مشابه کوک هولبین، به‌ویژه در میان هزاره‌های وردک) برای نقش‌های هندسی، و کوک ساتن برای پرکردن قاب‌های مربعی و مستطیلی اشاره کرد. نقش‌ها از منطقه‌ای به منطقه‌ی دیگر تفاوت دارند: هزاره‌های وردک بیشتر نقوش هندسیِ رنگارنگ و هزاره‌های غزنی طرح‌های مربعی و لوزی‌شکل منظم را ترجیح می‌دهند. دو شیوه‌ی متمایز نیز در دوخت لباس رایج است: «زمین‌دوزی» با دوخت متراکم روی سینه‌ی لباس‌های جشن، و «گل‌دوزی» با نقوش گلدار پیچان.\\n\\nاین هنر معمولاً با نخ ابریشمی رنگی روی پارچه‌ی پنبه‌ای یا ابریشمی و گاه با نوار و نخ طلایی‌رنگ برای لباس‌های جشن و کلاه کودکان انجام می‌شود و کاربردهایی چون چادر، کلاه، جلد قرآن، کیف، کمربند و سجاده دارد — میراثی که امروز هنرمندان هزاره در تبعید نیز برای زنده نگه‌داشتنش می‌کوشند.'},
      {'name': 'آشک و منتو', 'note': 'دو غذای سنتی محبوب؛ آشک خمیر پرشده با گشنیز و منتو با گوشت چرخ‌شده، هر دو با سس گوجه و ماست سرو می‌شوند.', 'full': 'آشک و منتو از محبوب‌ترین غذاهای سنتی هزاره‌ها و به‌طور کلی آشپزی افغانستان‌اند و هر دو در زمره‌ی خمیرهای پرشده (dumpling) جای می‌گیرند که ریشه در سنت آشپزی مشترک آسیای میانه و فلات ایران دارند.\\n\\nآشک با خمیر نازک و پری از تره یا گشنیز تازه تهیه می‌شود؛ خمیرها را می‌جوشانند و سپس با سس گوجه‌فرنگی، ماست چکیده و چاشنی نعناع خشک و سیر سرو می‌کنند. منتو نیز از همان خمیر ساخته می‌شود، اما پر آن گوشت چرخ‌شده (معمولاً گوسفندی) همراه با پیاز است؛ برخلاف آشک که آب‌پز می‌شود، منتو را بخارپز می‌کنند و همراه با سس گوجه، ماست و گاه خامه سرو می‌کنند.\\n\\nهر دو غذا، به‌ویژه در مهمانی‌ها و مناسبت‌های خانوادگی، جایگاه ویژه دارند و تهیه‌شان — از پهن‌کردن خمیر تا پرکردن دانه‌به‌دانه‌ی آن — اغلب کاری جمعی میان زنان خانواده است که خود به حفظ پیوندهای اجتماعی کمک می‌کند.'},
      {'name': 'قروت', 'note': 'لبنیات خشک‌شده و ذخیره‌شونده که در بسیاری از غذاهای محلی از جمله آش به کار می‌رود.', 'full': 'قروت (در برخی منابع «قروتو» یا نزدیک به «کشک» فارسی) یکی از کهن‌ترین شیوه‌های نگهداری لبنیات در آسیای میانه و فلات ایران است؛ ماستی تخمیرشده که برای نگهداری طولانی‌مدت، معمولاً به‌صورت گلوله یا قرص، در آفتاب خشک می‌شود.\\n\\nپیش از رواج یخچال، این روش به خانواده‌های کوچ‌نشین و روستایی امکان می‌داد لبنیات فصل بهار و تابستان را برای زمستان ذخیره کنند. برای مصرف، قروت خشک را در آب خیس یا آسیاب می‌کنند تا به شکل مایع یا خمیری غلیظ درآید و سپس به غذاهایی چون آش، دلدا (گندم کوبیده) و قروتی (نان خشک آغشته به قروت و روغن) افزوده می‌شود و طعمی ترش و شور به آن‌ها می‌بخشد.\\n\\nاین ماده در سراسر هزارستان — و همچنین در آشپزی تاجیکی و ازبکی با نام‌های مشابه — جایگاه ثابتی دارد و نمادی از سازگاری معیشتی مردم کوهستان با فصل‌های سخت و دسترسی محدود به مواد غذایی تازه در زمستان است.'},
      {'name': 'چپن و لباس محلی', 'note': 'پوشش سنتی با نقش و رنگ‌های متمایز هر منطقه، همراه با کلاه‌های سوزن‌دوزی‌شده.', 'full': 'چپن، ردای بلند و آستین‌دار که روی لباس معمولی پوشیده می‌شود، از نمادین‌ترین پوشش‌های سنتی مردان در سراسر آسیای میانه و افغانستان است. نام آن را برخی به واژه‌ی فارسی «چپان» (به‌معنای جامه‌ی کهنه) و برخی دیگر به ریشه‌ی چغتایی آن که خود از «جُبه»ی عربی می‌آید، نسبت می‌دهند.\\n\\nچپن معمولاً با نخ‌های رنگارنگ و طرح‌های راه‌راه یا هندسی تزیین می‌شود و در فصل سرما، به‌ویژه در مناسبت‌های رسمی و جشن‌ها، پوشیده می‌شود؛ در میان هزاره‌ها نیز، مانند تاجیک‌ها و ازبک‌ها، این پوشش بخشی از هویت بصری مردانه به‌شمار می‌رود. کلاه‌های سوزن‌دوزی‌شده، که با همان هنر سوزن‌دوزی زنانه‌ی هزارگی تزیین می‌شوند، معمولاً همراه چپن پوشیده می‌شوند و رنگ و نقش آن‌ها می‌تواند نشانه‌ی منطقه‌ی جغرافیایی دوزنده باشد.\\n\\nچپن در دهه‌های اخیر با پوشیدن آن توسط چهره‌های سیاسی افغان در دیدارهای رسمی بین‌المللی، بار دیگر به نماد وقار و هویت ملی افغانستان بدل شد — پیوندی زنده با راه‌های تجاری کهن و داد و ستد فرهنگی میان اقوام فارسی‌زبان، ترکی‌زبان و عربی‌زبان منطقه.'},
      {'name': 'بزکشی', 'note': 'ورزش سوارکاری سنتی رایج در افغانستان و آسیای میانه.', 'full': 'بزکشی، ورزش سوارکاری رایج در آسیای میانه که نام آن به‌معنای «کشیدن بز» است، ریشه در سنت‌های اقوام کوچ‌نشین آسیایی دارد که میان سده‌های دهم تا پانزدهم میلادی از سرزمین‌های چین و مغولستان به این منطقه مهاجرت کردند؛ برخی پژوهشگران خاستگاه آن را حتی تا دوران سکاها پیش می‌برند. این بازی طی مهاجرت‌های چندصدساله رو به غرب، تا دهه‌ی ۱۹۳۰ میلادی، به سراسر آسیای میانه راه یافت.\\n\\nامروزه اقوام گوناگون از جمله هزاره‌ها، ازبک‌ها، قرقیزها، ترکمن‌ها، قزاق‌ها، ایغورها، تاجیک‌ها، واخی‌ها و پشتون‌ها گونه‌هایی از بزکشی را بازی می‌کنند. بازی دو شکل اصلی دارد: «توده‌برای» که ساده‌تر است و در آن سوارکار باید لاشه را برداشته و از میان رقیبان بگذرد، و «قره‌جای» که پیچیده‌تر است و سوارکار باید لاشه را دور یک پرچم بچرخاند و در دایره‌ی امتیاز بیندازد. در قواعد استاندارد کابل، زمین بازی ۴۰۰ در ۴۰۰ متر، هر تیم ده سوارکار (پنج نفر در هر نیمه) و هر نیمه ۴۵ دقیقه است.\\n\\nسوارکاران ورزیده را «چاپنداز» می‌گویند که معمولاً در دهه‌ی چهل زندگی به اوج مهارت می‌رسند. بزکشی جایگاه ویژه‌ای در جشن‌های عروسی دارد و برگزاری آن اغلب هزینه‌ای است که خانواده‌ی داماد برای بزرگداشت جشن می‌پردازد. طالبان در دوره‌ی نخست حکومت خود این بازی را ممنوع کردند، اما پس از ۲۰۰۱ دوباره رواج یافت و همچنان در سراسر افغانستان، از جمله در مناطق هزاره‌نشین، برگزار می‌شود.'},
      {'name': 'عروسی سنتی', 'note': 'مراسمی چندروزه همراه با موسیقی دمبوره، آواز فلک و رسوم خانوادگی خاص هر منطقه.', 'full': 'عروسی در فرهنگ هزارگی، مانند بسیاری از جوامع سنتی افغانستان، رویدادی است که فراتر از پیوند دو فرد، دو خانواده و گاه دو محله را به هم می‌پیوندد و می‌تواند چند روز به طول انجامد.\\n\\nمراسم معمولاً با «خواستگاری» و سپس «نامزدی» (شیرینی‌خوری) آغاز می‌شود که در آن دو خانواده رسماً پیوند را می‌پذیرند. در روزهای منتهی به عروسی، محافل جداگانه‌ی زنانه با رقص، آواز و آرایش عروس (حنابندان) برگزار می‌شود. شب عروسی با نواختن دمبوره — ساز زهی نمادین موسیقی هزارگی — و آواز فلک، سبک آوازی کوهستانی منطقه، همراه است؛ در برخی مناطق، دف و دایره نیز به این آهنگ‌ها افزوده می‌شود.\\n\\nرسوم دقیق از منطقه‌ای به منطقه‌ی دیگر تفاوت دارد: در برخی نواحی، بزکشی جشن را همراهی می‌کند و در برخی دیگر، قصه‌گویی و دوبیتی‌خوانی بزرگان بخشی از شب عروسی است. مهریه، جهیزیه و مهمانی رسمی دیدار خانواده‌ها («خانه‌ترازی» یا دید و بازدید) از دیگر بخش‌های ثابت این مراسم‌اند. با گسترش دیاسپورای هزاره در کشورهای میزبان، بسیاری از این رسوم — از جمله موسیقی زنده‌ی دمبوره و فلک — همچنان در عروسی‌های نسل جدید حفظ می‌شود، هرچند با آمیزه‌ای از عناصر جدید.'},
      {'name': 'قصه‌گویی شفاهی', 'note': 'سنت روایت داستان توسط بزرگان خانواده؛ یکی از مهم‌ترین راه‌های انتقال حافظه‌ی جمعی میان نسل‌ها.', 'full': 'در جامعه‌ای که برای سده‌ها دسترسی محدودی به آموزش رسمی و کتابت داشته، روایت شفاهی مهم‌ترین ابزار حفظ و انتقال تاریخ، اخلاقیات و هویت قومی هزاره‌ها بوده است. شب‌نشینی‌های زمستانی، به‌ویژه در شب‌های بلند «چله»، فرصتی برای گردهمایی خانواده دور صندلی یا کرسی و شنیدن قصه از زبان مادربزرگ‌ها و پدربزرگ‌ها بوده است.\\n\\nاین قصه‌ها طیف گسترده‌ای را در بر می‌گیرند: افسانه‌های پندآموز، حکایت‌های عاشقانه، روایت‌های حماسی از دلاوری‌ها، و دوبیتی‌ها و فلک‌های نیمه‌شعر و نیمه‌آواز که تاریخ و رنج مشترک — از جمله دوران‌های سخت سرکوب و کوچ اجباری — را در قالب استعاره و کنایه با نسل بعد در میان می‌گذاشتند. زبان روایت، لهجه‌ی هزارگی با آمیزه‌ای از واژگان مغولی-ترکی کهن، خود بخشی جدایی‌ناپذیر از این میراث است.\\n\\nبا گسترش مهاجرت و پراکندگی جمعیت هزاره در کشورهای گوناگون، بسیاری از این روایت‌ها در معرض فراموشی قرار گرفته‌اند؛ از همین رو، تلاش برای ثبت و مکتوب‌کردن این حافظه‌ی جمعی — از جمله در پروژه‌هایی مانند همین برنامه — اهمیتی روزافزون یافته است.'},
      {'name': 'دف و دایره‌نوازی', 'note': 'سازهای کوبه‌ای رایج در مراسم شادی، عروسی و برخی آیین‌های مذهبی مناطق هزاره‌نشین.', 'full': 'دف، ساز کوبه‌ای حلقه‌ای که با پوستی کشیده روی قابی چوبی ساخته می‌شود، یکی از کهن‌ترین سازهای فلات ایران و آسیای میانه است؛ تصویرهایی از آن حتی در کتیبه‌ی بیستون (سده‌های پنجم و ششم پیش از میلاد) دیده می‌شود. در دوران ساسانی، دف همراه جشن‌های نوروزی و مجالس موسیقی دربار نواخته می‌شد.\\n\\nاین ساز، در کنار نمونه‌ی مشابه و کوچک‌تر خود یعنی دایره، در سراسر آسیای میانه‌ی فارسی‌زبان از جمله در مناطق هزاره‌نشین افغانستان رواج دارد و در مجالس شادی، عروسی و جشن‌های خانوادگی نواخته می‌شود. دف همچنین پیوندی دیرینه با آیین‌های صوفیانه دارد؛ از سده‌ی پانزدهم میلادی در محافل ذکر و سماع صوفیان به کار می‌رفته و باور بر این بوده که ریتم‌های پیچیده و فشرده‌ی آن می‌تواند نوازنده و شنونده را به حالتی از خلسه و تمرکز معنوی برساند.\\n\\nدر مراسم عروسی هزارگی، دف و دایره اغلب همراه با آواز فلک و دمبوره نواخته می‌شوند و ضرباهنگ اصلی رقص و پایکوبی مجلس را می‌سازند — سنتی که با وجود دهه‌ها جنگ و مهاجرت، همچنان در مجالس هزاره‌ها چه در داخل افغانستان و چه در دیاسپورا زنده مانده است.'},
      {'name': 'زیارت‌های محلی', 'note': 'مکان‌هایی مانند زیارت سخی در کابل، از مراکز مهم گردهمایی مذهبی و اجتماعی هزاره‌ها به‌شمار می‌روند.', 'full': 'زیارت سخی (مشهور به مسجد آبی یا شاه‌دوشمشیره‌ی کوچک، در ناحیه‌ی کارته‌سخی کابل) یکی از مهم‌ترین اماکن زیارتی شیعیان افغانستان و به‌ویژه هزاره‌هاست. به روایت رایج، بنای نخست آن به سال‌های ۱۷۶۷ تا ۱۷۶۸ میلادی و به دوران احمدشاه درانی بازمی‌گردد؛ هنگامی که وی عبای پیامبر(ص) را از فیض‌آباد به قندهار می‌برد، کاروان در نزدیکی کابل توقف کرد و به گفته‌ی روایت‌های محلی، مسافران در خواب مردی سبزپوش را در حال نیایش کنار آن دیدند که او را حضرت علی(ع) و شمشیرش را ذوالفقار شناختند. به دنبال این رؤیا، احمدشاه ساخت نخستین گنبد را بر همان نقطه بنیاد گذاشت. گنبد دوم در سال ۱۹۱۹ به دستور مادر امان‌الله‌خان افزوده شد و میان سال‌های ۲۰۰۸ تا ۲۰۱۶ چهار گنبد دیگر بر آن ساخته شد.\\n\\nاین زیارتگاه با کاشی‌های لعابی به سبک نو-صفوی و آیات و اشعار حک‌شده تزیین شده و مقصد اصلی زائران شیعه، به‌ویژه هزاره‌هاست. همین جایگاه ویژه در میان هزاره‌ها، آن را هدف خشونت نیز قرار داده است؛ از جمله در حمله‌ی انتحاری مارچ ۲۰۱۸ در جریان مراسم نوروز.\\n\\nفراتر از زیارت سخی، ده‌ها امام‌زاده و زیارتگاه کوچک‌تر در سراسر هزارستان — از بامیان تا غزنی و دایکندی — کانون گردهمایی‌های مذهبی، نذر و نیاز، و پیوندهای اجتماعی محلی‌اند و در تقویم فرهنگی هزاره‌ها جایگاهی پایدار دارند.'},
    ]),

